class FunctorialStateLift(nn.Module):
    def __init__(self, dim: int = 8):
        super().__init__()
        self.dim = dim

    def lift_state(self, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Correct lift: accumulate outer products K^T V over time.
        # This preserves historical correlations for lossless state recurrence.
        B, T, D = K.shape
        return torch.einsum('btd,btj->bdj', K, V)

